package com.srent.config;
import com.srent.booking.*;import com.srent.chat.*;import com.srent.property.*;import com.srent.room.*;import com.srent.user.*;import lombok.RequiredArgsConstructor;import org.springframework.boot.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;import java.math.BigDecimal;import java.time.LocalDate;
@Component @ConditionalOnProperty(name="app.seed-enabled",havingValue="true") @RequiredArgsConstructor
public class DevDataSeeder implements ApplicationRunner{private final UserRepository users;private final PropertyRepository properties;private final RoomRepository rooms;private final BookingRepository bookings;private final ConversationRepository conversations;private final MessageRepository messages;private final PasswordEncoder encoder;
@Override @Transactional public void run(ApplicationArguments args){if(users.existsByEmailIgnoreCase("admin@srent.local"))return;var student=user("student@srent.local","Student@123","Nguyễn Minh Sinh",User.Role.STUDENT);student.setDateOfBirth(LocalDate.of(2004,5,20));student.setPhone("0900000001");var landlord=user("landlord@srent.local","Landlord@123","Trần Văn Chủ",User.Role.LANDLORD);var admin=user("admin@srent.local","Admin@123","Quản trị S-Rent",User.Role.ADMIN);users.save(student);users.save(landlord);users.save(admin);var p=new Property();p.setOwner(landlord);p.setName("Khu trọ Sinh Viên Cầu Giấy");p.setDescription("Dữ liệu demo development");p.setAddressLine("12 Trần Thái Tông");p.setWard("Dịch Vọng Hậu");p.setDistrict("Cầu Giấy");p.setCity("Hà Nội");p.setLatitude(new BigDecimal("21.036500"));p.setLongitude(new BigDecimal("105.790800"));properties.save(p);var r1=room(p,"Phòng studio có gác",new BigDecimal("3500000"),new BigDecimal("24"),"wifi,điều hòa,gác xép");var r2=room(p,"Phòng cửa sổ lớn",new BigDecimal("2800000"),new BigDecimal("18"),"wifi,máy giặt chung");var r3=room(p,"Phòng demo chờ duyệt",new BigDecimal("2200000"),new BigDecimal("16"),"wifi");r3.setApprovalStatus(Room.ApprovalStatus.PENDING);rooms.save(r1);rooms.save(r2);rooms.save(r3);var c=new Conversation();c.setRoom(r1);c.setStudent(student);c.setLandlord(landlord);conversations.save(c);var m=new Message();m.setConversation(c);m.setSender(student);m.setContent("Chào anh/chị, phòng còn trống không ạ?");messages.save(m);var b=new Booking();b.setRoom(r2);b.setStudent(student);b.setLandlord(landlord);b.setMoveInDate(LocalDate.now().plusDays(14));b.setNote("Booking demo đang chờ xác nhận");bookings.save(b);}
private User user(String email,String password,String name,User.Role role){var u=new User();u.setEmail(email);u.setPasswordHash(encoder.encode(password));u.setFullName(name);u.setRole(role);return u;}private Room room(Property p,String title,BigDecimal price,BigDecimal area,String amenities){var r=new Room();r.setProperty(p);r.setTitle(title);r.setDescription("Phòng mẫu phục vụ tích hợp frontend");r.setMonthlyPrice(price);r.setAreaSqm(area);r.setAmenities(amenities);r.setMaxOccupants(2);r.setApprovalStatus(Room.ApprovalStatus.APPROVED);return r;}}
